INSERT INTO led_profiles (id, code, name, description, material, finish_surface, max_w_per_m, use_cases, created_at, available_lengths, includes_led, includes_power_supply) VALUES (16, 'PEI', 'Perfil Embutido Inclinado', 'Perfil de aluminio diseñado para embutir en muebles y placares. Su geometría asimétrica e inclinada dirige la luz hacia el interior, iluminando la ropa sin deslumbrar al usuario. Ideal para vestidores, placares y muebles a medida. 
Apto para tiras LED hasta 19 W/m y hasta 8 mm de ancho, con difusor que asegura una iluminación uniforme y confortable.', 'Aluminio 6061', 'Anodizado', 19, 'Placares y vestidores (ilumina la ropa sin encandilar).

Interiores de muebles de dormitorio.

Muebles de guardado en tiendas de indumentaria.

Armarios de cocina y despensas.

Muebles a medida donde se requiera luz funcional y discreta.', '2025-12-02T11:54:24.091738+00:00', '2m', true, true);
INSERT INTO led_profiles (id, code, name, description, material, finish_surface, max_w_per_m, use_cases, created_at, available_lengths, includes_led, includes_power_supply) VALUES (13, 'PIN', 'Perfil Invisible', 'Terminación techo/pared para placas de yeso. Sin grampas ni tapas visibles.', 'Aluminio 6061', 'Anodizado', 20, 'Soporta hasta 20w/m (12mm ancho)', '2025-12-02T11:54:16.813173+00:00', '2m', true, true);
INSERT INTO led_profiles (id, code, name, description, material, finish_surface, max_w_per_m, use_cases, created_at, available_lengths, includes_led, includes_power_supply) VALUES (12, 'PGA', 'Perfil Garganta', 'Perfil de aluminio para generar iluminación indirecta en paredes mediante sistema de falsa garganta.
Permite lograr un baño de luz uniforme, ocultando la fuente y evitando el deslumbramiento. Ideal para arquitectura residencial y comercial.', 'Aluminio 6061', 'Pintado', 20, 'Iluminación indirecta en paredes, pasillos, livings, dormitorios y locales comerciales.
Admite tiras LED de hasta 12 mm de ancho y potencias de hasta 20 W/m.', '2025-12-02T11:54:15.03909+00:00', 'A medida', true, true);
INSERT INTO led_profiles (id, code, name, description, material, finish_surface, max_w_per_m, use_cases, created_at, available_lengths, includes_led, includes_power_supply) VALUES (18, 'PEM', 'Perfil Embutir', 'Perfil de aluminio diseñado para embutir en techos o paredes de durlock, logrando una línea de luz continua, limpia y al ras de la superficie. Ideal para iluminación arquitectónica moderna.
Admite tiras LED hasta 30 W/m y hasta 12 mm de ancho. Compatible con placas de 5 a 25 mm. Incluye difusor opal que asegura una luz homogénea y reduce el deslumbramiento. Perfecto para proyectos residenciales y comerciales donde la iluminación se integra al diseño.', 'Aluminio 6061', 'Anodizado', 30, 'Líneas de luz continuas en techos de durlock.

Iluminación arquitectónica en paredes.

Pasillos y circulaciones.

Living, dormitorios y espacios comunes.

Oficinas y locales comerciales.', '2025-12-02T11:54:27.85866+00:00', '2m', true, true);
