INSERT INTO led_profiles (id, code, name, description, material, finish_surface, max_w_per_m, use_cases, created_at, available_lengths, includes_led, includes_power_supply) VALUES (19, 'PEX', 'Perfil Embutir XL', 'Perfil de aluminio para embutir en cielorrasos.
Versión ancha que permite instalar una o varias tiras LED, logrando una iluminación uniforme y de alto flujo.
Apto para placas de 8 a 20 mm de espesor.', 'Aluminio 6061', 'Anodizado', 50, 'Iluminación lineal en cielorrasos, pasillos, locales comerciales y espacios donde se requiere mayor potencia lumínica.
Permite instalar tiras LED de hasta 60 mm de ancho y potencias elevadas (hasta 50 W/m según configuración).', '2025-12-02T11:54:29.653549+00:00', '3m', true, true);
